@lru_cache(maxsize=2)
def _ledger(raw):
    if hashlib.sha256(raw).hexdigest()!=LEDGER_SHA256:raise ValueError('CPU-only source ledger changed')
    data=json.loads(raw)
    if data.get('schema')!='cpu-only-removal-history-v1' or data.get('baseline_commit')!='9969691d':raise ValueError('CPU-only source history scope changed')
    return data['files']

@lru_cache(maxsize=512)
def _before(encoded,digest):
    raw=zlib.decompress(base64.b85decode(encoded))
    if hashlib.sha256(raw).hexdigest()!=digest:raise ValueError('CPU-only historical preimage changed')
    return raw


# Unit 9 composes an exact UI-merge inverse before the unchanged CPU-only pins.
